using Xunit;using DocumentFormat.OpenXml.Packaging;using W=DocumentFormat.OpenXml.Wordprocessing;using Nd30.DocumentEngine.Model;using Nd30.DocumentEngine.Safety;using Nd30.LegalValidator.Authorization;using Nd30.LegalValidator.Model;using Nd30.LegalValidator.Remediation;using Nd30.LegalValidator.State;using Nd30.LegalValidator.Mutation;namespace Nd30.LegalValidator.Tests;public sealed class V25L4CMutationTests{static string Doc(W.JustificationValues? a=null,bool prot=false,bool missingDirect=false){if(a is null&&!missingDirect)a=W.JustificationValues.Left;var p=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".docx");using(var d=WordprocessingDocument.Create(p,DocumentFormat.OpenXml.WordprocessingDocumentType.Document)){var m=d.AddMainDocumentPart();m.Document=new W.Document(new W.Body());var pp=new W.ParagraphProperties();if(a is not null)pp.Append(new W.Justification{Val=a});m.Document.Body!.Append(new W.Paragraph(pp,new W.Run(new W.Text("Target paragraph"))),new W.Paragraph(new W.Run(new W.Text("Unrelated content"))));if(prot){var s=d.AddNewPart<DocumentSettingsPart>();s.Settings=new W.Settings(new W.DocumentProtection{Edit=W.DocumentProtectionValues.ReadOnly,Enforcement=true});}m.Document.Save();}return p;}static ValidationResult F()=>new("RULE.1",ValidationStatus.FAIL,"LEGAL_ERROR",new("SRC","loc"),new("paragraph","title","alignment"),"center","left",[new("semantic_component_detection",EvidenceAuthority.Authoritative,"ev-1",1,false,new Dictionary<string,string>{{"target_id","p1"}})],[],[],"applicable",1,PatchEligibility.ELIGIBLE,"test");static AuthorizedMutationRequest Q(string p,ParagraphAlignmentValue b=ParagraphAlignmentValue.LEFT,string? anchor=null){var f=F();var bind=new DocumentStateBinding(DocumentIdentityService.FromFile(p),RuleIdentity.From(f));var s=PackageSafetyPreflight.Inspect(p);var prop=new RemediationPlanner().Propose(f,s,"paragraph_alignment",bind);var t=new ParagraphTargetLocator("/word/document.xml","paragraph","p1","body/p[1]",anchor??ParagraphAlignmentMutationExecutor.Anchor("Target paragraph"),"paragraph.alignment");var i=MutationIntent.Create(prop,t,b,ParagraphAlignmentValue.CENTER);return AuthorizationBoundary.Authorize(prop,s,AuthorizationArtifact.Issue(prop,i),bind.ExpectedDocument,bind.ExpectedRule,i).Request!;}[Fact]public void Success_new_file_source_immutable_reopen_preserve(){var s=Doc();var o=s+".out.docx";var h=DocumentIdentityService.FromFile(s);try{var r=new ParagraphAlignmentMutationExecutor().Execute(s,o,Q(s));Assert.True(r.Success);Assert.Equal(h,DocumentIdentityService.FromFile(s));Assert.NotEqual(h,DocumentIdentityService.FromFile(o));using var d=WordprocessingDocument.Open(o,false);Assert.Equal(W.JustificationValues.Center,d.MainDocumentPart!.Document.Body!.Elements<W.Paragraph>().First().ParagraphProperties!.GetFirstChild<W.Justification>()!.Val!.Value);Assert.Contains("Unrelated content",d.MainDocumentPart.Document.InnerText);Assert.Equal(["ev-1"],r.EvidenceReferences);}finally{File.Delete(s);if(File.Exists(o))File.Delete(o);}}[Fact]public void Same_path_rejected(){var s=Doc();try{Assert.Equal(MutationOutcome.OUTPUT_PATH_INVALID,new ParagraphAlignmentMutationExecutor().Execute(s,s,Q(s)).Outcome);}finally{File.Delete(s);}}[Fact]public void Stale_no_output(){var s=Doc();var q=Q(s);File.AppendAllText(s,"x");var o=s+".o";try{Assert.Equal(MutationOutcome.STALE_DOCUMENT,new ParagraphAlignmentMutationExecutor().Execute(s,o,q).Outcome);Assert.False(File.Exists(o));}finally{File.Delete(s);}}[Fact]public void Wrong_auth_no_output(){var s=Doc();var q=Q(s);q=q with{Authorization=q.Authorization with{MutationIntentId="000000000000000000000000"}};var o=s+".o";try{Assert.Equal(MutationOutcome.AUTHORIZATION_REJECTED,new ParagraphAlignmentMutationExecutor().Execute(s,o,q).Outcome);Assert.False(File.Exists(o));}finally{File.Delete(s);}}[Fact]public void Missing_target(){var s=Doc();var o=s+".o";try{Assert.Equal(MutationOutcome.TARGET_NOT_FOUND,new ParagraphAlignmentMutationExecutor().Execute(s,o,Q(s,anchor:new string('f',64))).Outcome);}finally{File.Delete(s);}}[Fact]public void Before_mismatch(){var s=Doc();var o=s+".o";try{Assert.Equal(MutationOutcome.PRECONDITION_FAILED,new ParagraphAlignmentMutationExecutor().Execute(s,o,Q(s,ParagraphAlignmentValue.RIGHT)).Outcome);}finally{File.Delete(s);}}[Fact]public void Missing_direct_rejected(){var s=Doc(null,missingDirect:true);var o=s+".o";try{Assert.Equal(MutationOutcome.PROVENANCE_NOT_DIRECT,new ParagraphAlignmentMutationExecutor().Execute(s,o,Q(s)).Outcome);}finally{File.Delete(s);}}[Fact]public void Existing_output_rejected(){var s=Doc();var o=s+".o";File.WriteAllText(o,"x");try{Assert.Equal(MutationOutcome.OUTPUT_ALREADY_EXISTS,new ParagraphAlignmentMutationExecutor().Execute(s,o,Q(s)).Outcome);}finally{File.Delete(s);File.Delete(o);}}[Fact]public void Reapply_is_stale(){var s=Doc();var o=s+".docx";var o2=s+".2.docx";var q=Q(s);try{Assert.True(new ParagraphAlignmentMutationExecutor().Execute(s,o,q).Success);Assert.Equal(MutationOutcome.STALE_DOCUMENT,new ParagraphAlignmentMutationExecutor().Execute(o,o2,q).Outcome);}finally{File.Delete(s);if(File.Exists(o))File.Delete(o);if(File.Exists(o2))File.Delete(o2);}}}
